// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        vm.assume(amount > 0 && amount <= 100 ether);
        vm.assume(receiver != address(0) && receiver != address(c));
        address reverter = address(new Reverter());
        vm.deal(address(c), amount);
        vm.prank(address(this));
        bool ok = true;
        try c.sendTo(reverter, amount) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "contract should revert when receiver revert");
    }
}
contract Reverter { fallback() external payable { revert(); } }
